'use client';
import {apiFetch as fetch,subscribeChanges} from '../lib/api';
import Betting from './betting';
import Semifinals from './semifinals';
import AuthPanel,{ChangePassword,PasswordRecovery} from './auth-panel';
import React,{useState,useEffect,useCallback} from 'react';
import {ArrowUpRight,ArrowRight,ArrowLeft,ChevronRight,ChevronLeft,Search,Menu,X,Shield,Trophy,CalendarDays,Play,Users,Target,Newspaper,LayoutDashboard,Settings,RefreshCw,Plus,Pencil,Trash2,Download,Check,Clock,Radio,BarChart3,ArrowLeftRight,Flag,LogOut,Upload,Share2,ExternalLink,AlertCircle,Medal,Star,BookOpen,Activity,Eye} from 'lucide-react';
import {specs,tableRows,playerStats,youtubeId,standingsMatches} from '../lib/model';
const logoSrc=typeof location!=='undefined'&&location.protocol==='file:'?'assets/logo.jpg':'/assets/logo.jpg';
const links=[['/','Início'],['/jogos','Jogos'],['/semifinais','Semifinais'],['/apostas','Liga Bet'],['/classificacao','Classificação'],['/clubes','Clubes'],['/estatisticas','Estatísticas'],['/noticias','Notícias'],['/videos','Vídeos'],['/museu','Museu']];
const date=(v:string,full=false)=>v?new Date(/^\d{4}-\d{2}-\d{2}$/.test(v)?v+'T12:00:00-03:00':v).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'short',...(full?{hour:'2-digit',minute:'2-digit'}:{})}):'Data a definir';
const money=(v:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v);
function Empty({icon:Icon=Shield,title='Os próximos capítulos vêm aí.',text='As informações aparecerão aqui assim que forem publicadas pela liga.',small=false}:any){return <div className={'empty '+(small?'small':'')}><span className="empty-icon"><Icon size={25}/></span><h3>{title}</h3><p>{text}</p></div>}
function Badge({club,size=''}:any){return club?.image?<img className={'badge '+size} src={club.image} alt={'Escudo '+club.name}/>:<span className={'badge placeholder '+size} style={{color:club?.color||'#087653'}}><Shield/><b>{club?.short?.slice(0,3)||'BE'}</b></span>}
function Section({title,kicker,href,children,className=''}:any){return <section className={'section '+className}><div className="section-heading"><div>{kicker&&<span className="eyebrow">{kicker}</span>}<h2>{title}</h2></div>{href&&<a className="text-link" href={href}>Ver tudo <ArrowUpRight size={16}/></a>}</div>{children}</section>}
function Share(){const[ok,setOk]=useState(false);return <button className="button outline small-button" onClick={async()=>{try{if(navigator.share)await navigator.share({title:document.title,url:location.href});else{await navigator.clipboard.writeText(location.href);setOk(true)}}catch{}}}><Share2 size={15}/>{ok?'Link copiado':'Compartilhar'}</button>}
function Video({url}:any){const id=youtubeId(url||'');return id?<iframe className="video-player" src={'https://www.youtube-nocookie.com/embed/'+id} title="Vídeo da liga" allow="accelerometer; autoplay; encrypted-media; picture-in-picture" allowFullScreen loading="lazy"/>:null}
function Inline({text}:any){return <>{String(text).split(/(\*\*[^*]+\*\*|\*[^*]+\*|https:\/\/[^\s]+)/g).map((s,i)=>s.startsWith('**')?<strong key={i}>{s.slice(2,-2)}</strong>:s.startsWith('*')?<em key={i}>{s.slice(1,-1)}</em>:s.startsWith('https://')?<a href={s} target="_blank" rel="noopener noreferrer" key={i}>{s}</a>:s)}</>}
function Content({text}:any){return <div className="rich-text">{String(text||'').split('\n').map((line,i)=>line.startsWith('## ')?<h2 key={i}><Inline text={line.slice(3)}/></h2>:line.startsWith('### ')?<h3 key={i}><Inline text={line.slice(4)}/></h3>:<p key={i}><Inline text={line}/></p>)}</div>}
export default function Portal({path}:{path:string}){
const [data,setData]=useState<any>(null),[error,setError]=useState(''),[seasonId,setSeasonId]=useState(''),[nav,setNav]=useState(false),[search,setSearch]=useState(''),[searchOpen,setSearchOpen]=useState(false),[round,setRound]=useState(''),[status,setStatus]=useState(''),[category,setCategory]=useState(''),[phase,setPhase]=useState(''),[clubFilter,setClubFilter]=useState(''),[compareA,setCompareA]=useState(''),[compareB,setCompareB]=useState('');
const admin=path.startsWith('/admin');
const load=useCallback(async()=>{try{const r=await fetch('/api/data'+(admin?'?admin=1':''));const d:any=await r.json();if(!r.ok)throw new Error(d.error||'Não foi possível carregar.');setData(d);setError('');setSeasonId(s=>s||d.seasons.find((s:any)=>s.status==='Em andamento')?.id||d.seasons[d.seasons.length-1]?.id||'')}catch(e:any){setError(e.message)}},[admin]);
useEffect(()=>{load();return subscribeChanges(load)},[load]);
const d=data||Object.fromEntries(Object.keys(specs).map(k=>[k,[]]));const season=d.seasons.find((x:any)=>x.id===seasonId);const external=d.config?.mode==='external';const scopedExternal=(d.external||[]).filter((e:any)=>e.tournament_id===d.config?.tournament&&(!seasonId||e.season_id===seasonId));const clubs=d.clubs.filter((c:any)=>external?c.source==='copafacil'&&c.tournament_id===d.config?.tournament:c.source!=='copafacil');const club=(id:string)=>d.clubs.find((c:any)=>c.id===id);const player=(id:string)=>d.players.find((c:any)=>c.id===id);const allMatches=d.matches.filter((m:any)=>(!seasonId||m.season_id===seasonId)&&(external?m.source==='copafacil'&&m.tournament_id===d.config?.tournament:m.source!=='copafacil'));const events=d.events.filter((e:any)=>allMatches.some((m:any)=>m.id===e.match_id));const appearances=d.appearances.filter((e:any)=>allMatches.some((m:any)=>m.id===e.match_id));const seasonalClubIds=new Set([...allMatches.flatMap((m:any)=>[m.home_id,m.away_id]),...d.memberships.filter((m:any)=>m.season_id===seasonId).map((m:any)=>m.club_id)]);const leagueMatches=standingsMatches(allMatches,d.phases,d.rounds);const semiMatches=allMatches.filter((m:any)=>/^semifina/i.test(m.phase)).sort((a:any,b:any)=>a.id.localeCompare(b.id));const standing=tableRows(clubs.filter((c:any)=>seasonalClubIds.has(c.id)),leagueMatches,season,round?+round:undefined);const seasonTotals=(d.player_totals||[]).filter((t:any)=>t.season_id===seasonId);const stats=playerStats(d.players,events,appearances,seasonTotals);const sNews=[...d.news].sort((a:any,b:any)=>(b.featured==='Sim'?1:0)-(a.featured==='Sim'?1:0)||b.created_at.localeCompare(a.created_at));const trophies=d.titles.filter((t:any)=>!seasonId||t.season_id===seasonId);const scopedAwards=d.awards.filter((a:any)=>!seasonId||a.season_id===seasonId);const transfers=d.transfers.filter((t:any)=>t.status==='Confirmada'&&(!seasonId||t.season_id===seasonId)).sort((a:any,b:any)=>b.date.localeCompare(a.date));
function Match({m,compact=false}:any){return <a href={'/jogos/'+m.id} className={'match '+(compact?'compact':'')}><div className="match-meta"><span className={m.status==='Ao vivo'?'live':''}>{m.status==='Ao vivo'&&<i/>}{m.status==='Agendado'?date(m.kickoff,true):m.status}</span><span>{m.round}ª rodada</span></div><div className="match-team"><Badge club={club(m.home_id)}/><span className="grow"><b>{club(m.home_id)?.name}</b><small className="match-manager">{club(m.home_id)?.manager}</small></span><strong>{m.home_score??'–'}</strong></div><div className="match-team"><Badge club={club(m.away_id)}/><span className="grow"><b>{club(m.away_id)?.name}</b><small className="match-manager">{club(m.away_id)?.manager}</small></span><strong>{m.away_score??'–'}</strong></div>{!compact&&<div className="match-foot">{m.phase}<ArrowUpRight size={14}/></div>}</a>}
function Table({short=false}:any){if(external){const tables=scopedExternal.filter((x:any)=>x.kind==='table');return tables.length?<div>{tables.map((item:any)=><div key={item.id} className="table-wrap"><h3 className="table-caption">{item.data.stageTitle}</h3><table><thead><tr><th>#</th><th>Clube</th>{item.data.header?.map((h:any,i:number)=><th key={i}>{h.title1}</th>)}</tr></thead><tbody>{(short?item.data.teams.slice(0,5):item.data.teams).map((t:any)=><tr key={t.id}><td>{t.position}</td><td>{t.name}</td>{item.data.header?.map((h:any,i:number)=><td key={i}>{t.tableData?.find((x:any)=>String(x.cod)===String(h.cod))?.value??'—'}</td>)}</tr>)}</tbody></table></div>)}</div>:<Empty small icon={BarChart3} title="Aguardando sincronização" text="A tabela será exibida após a primeira importação."/>}
return standing.length?<div className="table-wrap"><table><thead><tr><th>#</th><th>Clube</th><th>PTS</th><th>J</th>{!short&&<><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th></>}<th>SG</th>{!short&&<><th>APR%</th><th>Últimos 5</th></>}</tr></thead><tbody>{(short?standing.slice(0,5):standing).map((c:any,i:number)=><tr key={c.id}><td className={i<(season?.qualify||0)?'qualify':i>=standing.length-(season?.relegate||0)?'relegate':''}>{i+1}</td><td><a className="table-club" href={'/clubes/'+c.id}><Badge club={c}/>{c.name}</a></td><td><strong>{c.points}</strong></td><td>{c.played}</td>{!short&&<><td>{c.wins}</td><td>{c.draws}</td><td>{c.losses}</td><td>{c.gf}</td><td>{c.ga}</td></>}<td>{c.gd>0?'+':''}{c.gd}</td>{!short&&<><td>{c.played?Math.round(c.points/(c.played*3)*100):0}%</td><td><div className="form-dots">{c.form.slice(-5).map((f:string,j:number)=><span className={'form-'+f} key={j}>{f}</span>)}</div></td></>}</tr>)}</tbody></table></div>:<Empty small icon={BarChart3} title="A disputa começa em breve" text="A classificação será calculada a partir das partidas encerradas."/>}
function NewsCard({n,hero=false}:any){return <a className={'news-card '+(hero?'feature-news':'')} href={'/noticias/'+n.id}><div className="news-image">{n.image?<img src={n.image} alt=""/>:<img src={logoSrc} alt=""/>}<span className="tag">{n.category}</span></div><div className="news-copy"><small>{date(n.created_at)} · {n.author}</small><h3>{n.title}</h3><p>{n.summary}</p><span className="read">Ler matéria <ArrowUpRight size={17}/></span></div></a>}
function Rankings({short=false,metric='goals'}:any){const scoped=path==='/estatisticas'?playerStats(d.players.filter((p:any)=>!clubFilter||d.memberships.some((m:any)=>m.player_id===p.id&&m.club_id===clubFilter&&m.season_id===seasonId)),events.filter((e:any)=>(!round||allMatches.find((m:any)=>m.id===e.match_id)?.round===+round)&&(!clubFilter||e.club_id===clubFilter)),appearances.filter((e:any)=>(!round||allMatches.find((m:any)=>m.id===e.match_id)?.round===+round)&&(!clubFilter||e.club_id===clubFilter)),round?[]:seasonTotals.filter((t:any)=>!clubFilter||t.club_id===clubFilter)):stats;const ranked=[...scoped].filter((s:any)=>Number(s[metric])>0).sort((a:any,b:any)=>b[metric]-a[metric]);if(!ranked.length)return <Empty small icon={Target} title="Quem vai liderar a artilharia?" text="Os gols e as assistências serão registrados lance a lance."/>;return <div>{!short&&seasonTotals.length>0&&!round&&<p className="muted">Totais da temporada informados pela organização. Não são somados aos lances. O filtro por rodada considera somente lances registrados.</p>}<div className="ranking-list">{(short?ranked.slice(0,5):ranked).map((p:any,i:number)=><a href={'/jogadores/'+p.id} key={p.id}><span className="rank-num">{String(i+1).padStart(2,'0')}</span>{p.image?<img src={p.image} alt=""/>:<span className="avatar"><Users size={20}/></span>}<span className="grow"><b>{p.name}</b><small>{club(d.memberships.find((m:any)=>m.player_id===p.id&&m.season_id===seasonId&&!m.ended)?.club_id)?.name||p.position}</small></span><strong>{metric==='rating'?p[metric]?.toFixed(1)||'—':p[metric]}</strong></a>)}</div></div>}
function Heading({title,sub,kicker='BRASILEIRÃO EFOOTBALL',children}:any){return <div className="page-heading"><div><span className="eyebrow">{kicker}</span><h1>{title}</h1>{sub&&<p>{sub}</p>}</div>{children}</div>}
const selectedMatches=allMatches.filter((m:any)=>(!round||m.round===+round)&&(!status||m.status===status)&&(!phase||m.phase===phase)&&(!clubFilter||[m.home_id,m.away_id].includes(clubFilter)));
function MatchFilters(){return <div className="filters"><select aria-label="Rodada" value={round} onChange={e=>setRound(e.target.value)}><option value="">Todas as rodadas</option>{[...new Set(allMatches.map((m:any)=>m.round))].sort((a:any,b:any)=>a-b).map((r:any)=><option key={r} value={r}>{r}ª rodada</option>)}</select><select aria-label="Fase" value={phase} onChange={e=>setPhase(e.target.value)}><option value="">Todas as fases</option>{[...new Set([...allMatches.map((m:any)=>m.phase),...d.phases.filter((p:any)=>p.season_id===seasonId).map((p:any)=>p.name)])].map((s:any)=><option key={s}>{s}</option>)}</select><select aria-label="Status" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos os status</option>{['Agendado','Ao vivo','Encerrado','Adiado'].map(s=><option key={s}>{s}</option>)}</select><select aria-label="Clube" value={clubFilter} onChange={e=>setClubFilter(e.target.value)}><option value="">Todos os clubes</option>{clubs.map((c:any)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div>}
function Videos({list}:any){return list.length?<div className="cards three">{list.map((v:any)=><a key={v.id} href={'/videos/'+v.id} className="video-card"><div className="video-thumb"><img src={v.image||'https://i.ytimg.com/vi/'+youtubeId(v.url)+'/hqdefault.jpg'} alt=""/><span><Play fill="currentColor" size={22}/></span></div><span className="eyebrow">{v.category}</span><h3>{v.title}</h3></a>)}</div>:<Empty icon={Play} title="O espetáculo merece replay" text="Golaços, defesas e melhores momentos da liga estarão aqui."/>}
let content:React.ReactNode;
if(admin)content=data?<Admin d={d} load={load}/>:null;
else if(path==='/recuperar-senha')content=<PasswordRecovery/>;
else if(path==='/apostas')content=<Betting d={d} seasonId={seasonId} reload={load}/>;
else if(path==='/semifinais')content=<Semifinals matches={semiMatches} clubs={clubs} season={season} finalMatch={allMatches.find((m:any)=>/^final$/i.test(m.phase))}/>;
else if(path==='/')content=<>
<div className="home-topline"><span><i className="green-dot"/>O portal da nossa liga</span><span>Competição. Comunidade. História.</span></div>
<div className="score-strip"><a className="score-label" href="/jogos"><CalendarDays size={20}/><strong>Central<br/>de jogos</strong><ArrowUpRight size={16}/></a>{allMatches.length?allMatches.slice().sort((a:any,b:any)=>(a.status==='Ao vivo'?-1:1)-(b.status==='Ao vivo'?-1:1)).slice(0,5).map((m:any)=><Match key={m.id} m={m} compact/>):<div className="score-pending"><div><span className="pill"><Clock size={12}/> AGENDA DA LIGA</span><strong>A próxima disputa começa aqui.</strong><span>Acompanhe os confrontos assim que a tabela for publicada.</span></div><a href="/jogos">Ver calendário <ArrowRight size={17}/></a></div>}</div>
{semiMatches.length>0&&<a className="semi-home-link" href="/semifinais"><Trophy size={24}/><span><small>A DISPUTA PELO TÍTULO</small><strong>As semifinais estão definidas.</strong></span><span>Conheça os confrontos <ArrowUpRight size={18}/></span></a>}
<div className="hero-grid">{sNews[0]?<NewsCard n={sNews[0]} hero/>:d.banners[0]?<a className="welcome-hero" href={d.banners[0].url||'/jogos'} style={d.banners[0].image?{backgroundImage:`url(${d.banners[0].image})`}:{}}><div className="hero-copy"><span className="eyebrow">A NOSSA LIGA</span><h1>{d.banners[0].title}</h1><p>{d.banners[0].description}</p><span className="button">Conheça a liga <ArrowRight size={17}/></span></div></a>:<div className="welcome-hero"><img className="hero-art" src={logoSrc} alt="Logo oficial do Brasileirão eFootball"/><div className="hero-copy"><span className="hero-label">PAIXÃO REAL. FUTEBOL VIRTUAL.</span><h1>O jogo é virtual.<br/>A emoção<br/><em>é de verdade.</em></h1><p>A casa do Brasileirão eFootball.<br/>Cada rodada, cada conquista, cada história.</p><a className="button" href="/jogos">Acompanhe a liga <ArrowUpRight size={18}/></a></div><span className="hero-bottom">BRASILEIRÃO EFOOTBALL <span>DESDE O PRIMEIRO APITO ↗</span></span></div>}
<aside className="hero-sidebar"><a className="spotlight-card" href="/clubes"><span className="eyebrow">OS PROTAGONISTAS</span><div className="shield-composition"><Shield size={75}/><Shield size={105}/><Shield size={65}/></div><h3>Uma liga.<br/>Muitas paixões.</h3><p>Conheça os clubes e os elencos que entram em campo.</p><span className="text-link">Explore os clubes <ArrowUpRight size={16}/></span></a><a className="museum-mini" href="/museu"><span className="mini-trophy"><Trophy size={32}/></span><div><span className="eyebrow">A GLÓRIA FICA</span><h3>Nosso museu</h3><p>O lugar de quem fez história.</p></div><ArrowUpRight size={18}/></a></aside></div>
<div className="home-tables"><Section title="A corrida pelo topo" kicker="CLASSIFICAÇÃO" href="/classificacao"><div className="panel"><div className="panel-caption"><span>{season?.name||'Campeonato'}</span><span>Pontos corridos</span></div><Table short/><a className="panel-footer" href="/classificacao">Classificação completa <ArrowRight size={16}/></a></div></Section><Section title="Faro de gol" kicker="ARTILHARIA" href="/estatisticas"><div className="panel"><div className="panel-caption"><span>Os goleadores da liga</span><Target size={16}/></div><Rankings short/><a className="panel-footer" href="/estatisticas">Todas as estatísticas <ArrowRight size={16}/></a></div></Section></div>
<Section title="Dentro e fora de campo" kicker="ÚLTIMAS NOTÍCIAS" href="/noticias">{sNews.length?<div className="cards three">{sNews.slice(0,3).map((n:any)=><NewsCard n={n} key={n.id}/>)}</div>:<div className="news-empty"><Newspaper size={38}/><div><h3>A informação também entra em jogo.</h3><p>Notícias, bastidores e comunicados oficiais. Em breve, as primeiras manchetes.</p></div><a href="/noticias" className="round-arrow"><ArrowUpRight size={22}/></a></div>}</Section>
<div className="home-tables"><Section title="Vem aí na liga" kicker="PRÓXIMOS CONFRONTOS" href="/jogos"><div className="panel">{allMatches.filter((m:any)=>m.status==='Agendado').length?allMatches.filter((m:any)=>m.status==='Agendado').slice(0,3).map((m:any)=><Match key={m.id} m={m}/>):<Empty small icon={CalendarDays} title="Prepare a torcida" text="Os próximos jogos serão anunciados aqui."/>}</div></Section><Section title="Mercado da bola" kicker="TRANSFERÊNCIAS" href="/transferencias"><div className="panel">{transfers.length?transfers.slice(0,4).map((t:any)=><div className="transfer-row" key={t.id}><span className="avatar"><ArrowLeftRight size={20}/></span><div className="grow"><a href={'/jogadores/'+t.player_id}><b>{player(t.player_id)?.name}</b></a><small>{club(t.from_id)?.name||'Sem clube'} → {club(t.to_id)?.name}</small></div><span className="tag green">Confirmada</span></div>):<Empty small icon={ArrowLeftRight} title="O mercado está no radar" text="As contratações confirmadas pela liga aparecerão aqui."/>}</div></Section></div>
<Section title="O lance não acaba no apito" kicker="PLAY NA LIGA" href="/videos"><Videos list={d.videos.slice(0,3)}/></Section>
<Section title="Quem fez a diferença" kicker="CRAQUES DA RODADA" href="/premiacoes">{scopedAwards.length?<div className="cards three">{scopedAwards.slice(0,3).map((a:any)=><a href="/premiacoes" className="award-card" key={a.id}><Star/><span className="eyebrow">{a.name}</span><h3>{player(a.player_id)?.name||club(a.club_id)?.name||a.description}</h3><p>{a.round?a.round+'ª rodada':season?.name}</p></a>)}</div>:<div className="quiet-empty"><Star size={20}/><p>As atuações de destaque terão seu lugar aqui.</p><a href="/premiacoes">Ver premiações <ArrowRight size={15}/></a></div>}</Section>
<a className="history-banner" href="/museu"><div><span className="eyebrow">MAIS QUE UM CAMPEONATO. UM LEGADO.</span><h2>A taça passa.<br/>A história permanece.</h2><p>{trophies[0]?`${club(trophies[0].club_id)?.name} · ${trophies[0].name}`:'Relembre os campeões, os recordes e os nomes que marcaram a liga.'}</p><span className="button outline">Entre no museu <ArrowUpRight size={17}/></span></div><Trophy className="history-cup" strokeWidth={1}/><span className="history-no">01 / ∞</span></a>
</>;
else if(path==='/jogos'||path==='/calendario')content=<><Heading title="Cada rodada, uma história." kicker="CENTRAL DE JOGOS" sub="Calendário, placares e todos os detalhes dos confrontos."/><MatchFilters/><div className="round-tabs" aria-label="Rodadas"><button className={!round?'active':''} onClick={()=>setRound('')}>Todas</button>{[...new Set([...allMatches.map((m:any)=>m.round),...d.rounds.filter((r:any)=>d.phases.some((p:any)=>p.id===r.phase_id&&p.season_id===seasonId&&(!phase||p.name===phase))).map((r:any)=>r.number)])].sort((a:any,b:any)=>a-b).map((n:any)=><button key={n} className={round===String(n)?'active':''} onClick={()=>setRound(String(n))}>{n}ª rodada</button>)}</div>{selectedMatches.length?<div className="cards three">{selectedMatches.map((m:any)=><Match m={m} key={m.id}/>)}</div>:<Empty icon={CalendarDays} title={allMatches.length?'Nenhum jogo neste filtro':'A tabela está a caminho'} text="Confira os jogos assim que forem cadastrados pela organização."/>}{external&&<ExternalMatches data={scopedExternal}/>}</>;
else if(path.startsWith('/jogos/')){const m=d.matches.find((m:any)=>m.id===path.split('/')[2]);content=m?<><a href="/jogos" className="back"><ArrowLeft size={16}/>Central de jogos</a><div className="match-center"><span className="eyebrow">{m.phase} · {m.round}ª RODADA</span><div className="big-score"><a href={'/clubes/'+m.home_id}><Badge club={club(m.home_id)} size="large"/><h2>{club(m.home_id)?.name}</h2></a><div><span className={'pill '+(m.status==='Ao vivo'?'live':'')}>{m.status}</span><strong>{m.home_score??'–'} <i>:</i> {m.away_score??'–'}</strong><small>{date(m.kickoff,true)}</small></div><a href={'/clubes/'+m.away_id}><Badge club={club(m.away_id)} size="large"/><h2>{club(m.away_id)?.name}</h2></a></div><Share/></div><div className="home-tables"><Section title="O jogo, lance a lance" kicker="LINHA DO TEMPO"><div className="panel timeline">{d.events.filter((e:any)=>e.match_id===m.id).sort((a:any,b:any)=>b.minute-a.minute).map((e:any)=><div key={e.id}><b>{e.minute}'</b><span className="avatar">{e.type.startsWith('Gol')?<Target size={19}/>:<Flag size={19}/>}</span><span><strong>{e.type} · {player(e.player_id)?.name||club(e.club_id)?.name}</strong><p>{e.assist_id?'Assistência: '+player(e.assist_id)?.name+'. ':''}{e.notes}</p></span></div>)}{!d.events.some((e:any)=>e.match_id===m.id)&&<Empty small icon={Activity} title="Aguardando os lances"/>}</div></Section><Section title="Escalações e números" kicker="A PARTIDA"><div className="panel padded">{[['possession','Posse de bola (%)'],['shots','Finalizações'],['on_target','No alvo'],['corners','Escanteios']].map(([k,l])=>m['home_'+k]!=null||m['away_'+k]!=null?<div className="comparison" key={k}><strong>{m['home_'+k]??'—'}</strong><span>{l}</span><strong>{m['away_'+k]??'—'}</strong></div>:null)}<Content text={m.notes||'As informações da partida ainda não foram publicadas.'}/>{d.appearances.filter((a:any)=>a.match_id===m.id).map((a:any)=><div className="list-line" key={a.id}><a href={'/jogadores/'+a.player_id}>{player(a.player_id)?.name}</a><small>{a.starter==='Sim'?'Titular':'Reserva'} · {a.rating??'Sem nota'}</small></div>)}</div></Section></div><Section title="Histórico de confrontos"><div className="cards three">{d.matches.filter((g:any)=>g.id!==m.id&&g.status==='Encerrado'&&[m.home_id,m.away_id].includes(g.home_id)&&[m.home_id,m.away_id].includes(g.away_id)).map((g:any)=><Match m={g} key={g.id}/>)}</div>{!d.matches.some((g:any)=>g.id!==m.id&&g.status==='Encerrado'&&[m.home_id,m.away_id].includes(g.home_id)&&[m.home_id,m.away_id].includes(g.away_id))&&<Empty small title="Primeiros encontros" text="Não há outros confrontos encerrados cadastrados entre estas equipes."/>}</Section><Section title="Melhores momentos"><Videos list={d.videos.filter((v:any)=>v.match_id===m.id)}/></Section></>:<NotFound/>}
else if(path==='/classificacao')content=<><Heading title="A corrida pelo topo." kicker="CLASSIFICAÇÃO" sub="Cada ponto conta. Acompanhe a disputa pela liderança."/><div className="filters"><span>{season?.name||'Temporada a definir'}</span><select aria-label="Até a rodada" value={round} onChange={e=>setRound(e.target.value)}><option value="">Classificação atual</option>{[...new Set(allMatches.map((m:any)=>m.round))].sort((a:any,b:any)=>a-b).map((r:any)=><option key={r} value={r}>Até a {r}ª rodada</option>)}</select><a className="text-link" href="/regulamento">Critérios e regulamento <ArrowUpRight size={15}/></a></div><div className="panel"><Table/></div><p className="table-note"><span className="green-dot"/> Classificação · <span className="red-dot"/> Rebaixamento (quando configurados). PTS: pontos · J: jogos · SG: saldo de gols.</p><p className="muted">Desempate: {season?.tiebreakers==='points,gd,gf,wins'?'pontos, saldo de gols, gols pró e vitórias':'pontos, vitórias, saldo de gols e gols pró'}. Empate absoluto: ordem alfabética para exibição.</p></>;
else if(path==='/clubes')content=<><Heading title="Uma liga. Muitas paixões." kicker="CLUBES E ELENCOS" sub="Os escudos, as camisas e os protagonistas do campeonato."/><div className="filters"><Search size={18}/><input aria-label="Buscar clube" placeholder="Busque seu clube" value={search} onChange={e=>setSearch(e.target.value)}/><a className="text-link" href="/comparar">Comparar clubes <ArrowLeftRight size={16}/></a></div>{clubs.length?<div className="cards four">{clubs.filter((c:any)=>c.name.toLowerCase().includes(search.toLowerCase())).map((c:any)=><a className="club-card" href={'/clubes/'+c.id} key={c.id} style={{'--club-color':c.color||'#087653'} as any}><span className="club-abbr">{c.short}</span><Badge club={c} size="large"/><h2>{c.name}</h2><p>{c.manager||'Clube da liga'}</p><span>Conheça o elenco <ArrowUpRight size={16}/></span></a>)}</div>:<Empty icon={Shield} title="Os escudos vão entrar em campo" text="Os clubes participantes serão apresentados após o cadastro pela organização."/>}</>;
else if(path.startsWith('/clubes/')){const c=club(path.split('/')[2]),s=standing.find((x:any)=>x.id===c?.id);const members=d.memberships.filter((m:any)=>m.club_id===c?.id&&m.season_id===seasonId&&!m.ended);content=c?<><div className="club-profile"><Badge club={c} size="large"/><div><span className="eyebrow">CLUBE DO BRASILEIRÃO EFOOTBALL</span><h1>{c.name}</h1><p>{c.manager?'Técnico / responsável: '+c.manager:'O clube da nossa liga.'}</p></div><Share/></div><div className="stat-boxes">{[['Pontos',s?.points||0],['Jogos',s?.played||0],['Gols marcados',s?.gf||0],['Títulos',d.titles.filter((t:any)=>t.club_id===c.id).length]].map(([l,v])=><div key={l}><strong>{v}</strong><span>{l}</span></div>)}</div>{c.bio&&<Content text={c.bio}/>}<Section title="Quem veste a camisa" kicker="ELENCO">{c.formation&&<p className="muted">Formação: {c.formation}</p>}{members.length?<div className="cards four">{members.map((m:any)=>{const p=player(m.player_id);return p?<a key={m.id} href={'/jogadores/'+p.id} className="player-card"><div className="player-image">{p.image?<img src={p.image} alt={p.name}/>:<Users size={65}/>}<b className="overall">{p.overall??'—'}<small>{p.position||'Posição não informada'}</small></b></div><span className="eyebrow">{m.role||'Função não informada'} · #{m.number||'—'}</span><h3>{p.name}</h3></a>:null})}</div>:<Empty icon={Users} title="Elenco em preparação" text="A organização ainda não cadastrou os jogadores desta temporada."/>}</Section><Section title="Agenda e resultados"><div className="cards three">{allMatches.filter((m:any)=>[m.home_id,m.away_id].includes(c.id)).map((m:any)=><Match m={m} key={m.id}/>)}</div></Section><Section title="Na sala de troféus"><div className="cards three">{d.titles.filter((t:any)=>t.club_id===c.id).map((t:any)=><a className="award-card" href={'/temporadas/'+t.season_id} key={t.id}><Trophy/><h3>{t.name}</h3><p>{d.seasons.find((s:any)=>s.id===t.season_id)?.name}</p></a>)}</div></Section></>:<NotFound/>}
else if(path.startsWith('/jogadores/')){const p=stats.find((p:any)=>p.id===path.split('/')[2]);content=p?<><div className="club-profile">{p.image?<img className="player-portrait" src={p.image} alt={p.name}/>:<span className="profile-avatar"><Users size={64}/></span>}<div><span className="eyebrow">{p.position} · OVERALL {p.overall??'—'}</span><h1>{p.name}</h1><p>{club(d.memberships.find((m:any)=>m.player_id===p.id&&m.season_id===seasonId&&!m.ended)?.club_id)?.name||'Sem clube cadastrado nesta temporada'}</p></div><Share/></div><div className="stat-boxes">{[['Gols',p.goals],['Assistências',p.assists],['Jogos',p.played],['Participações em gols',p.contributions]].map(([l,v])=><div key={l}><strong>{v}</strong><span>{l}</span></div>)}</div><Content text={p.bio}/><Section title="Temporada por temporada" kicker="EVOLUÇÃO ESTATÍSTICA"><div className="panel table-wrap"><table><thead><tr><th>Temporada</th><th>Jogos</th><th>Gols</th><th>Assistências</th></tr></thead><tbody>{d.seasons.map((s:any)=>{const ids=new Set(d.matches.filter((m:any)=>m.season_id===s.id).map((m:any)=>m.id));const row=playerStats([p],d.events.filter((e:any)=>ids.has(e.match_id)),d.appearances.filter((a:any)=>ids.has(a.match_id)),(d.player_totals||[]).filter((t:any)=>t.season_id===s.id))[0];return <tr key={s.id}><td>{s.name}</td><td>{row.played}</td><td>{row.goals}</td><td>{row.assists}</td></tr>})}</tbody></table></div></Section><Section title="A trajetória"><div className="panel padded">{d.memberships.filter((m:any)=>m.player_id===p.id).map((m:any)=><div className="list-line" key={m.id}><a href={'/clubes/'+m.club_id}>{club(m.club_id)?.name}</a><span>{d.seasons.find((s:any)=>s.id===m.season_id)?.name} · {m.started||'Entrada não informada'} — {m.ended||'Atual'}</span></div>)}</div></Section><Section title="Reconhecimento"><div className="cards three">{d.awards.filter((a:any)=>a.player_id===p.id).map((a:any)=><div className="award-card" key={a.id}><Medal/><h3>{a.name}</h3><p>{a.description}</p></div>)}</div></Section><Section title="Em ação"><Videos list={d.videos.filter((v:any)=>v.player_id===p.id)}/></Section></>:<NotFound/>}
else if(path==='/estatisticas')content=<><Heading title="O jogo em números." kicker="ESTATÍSTICAS" sub="Gols, assistências e desempenho, a partir dos registros oficiais da liga."/><div className="filters"><select aria-label="Filtrar estatísticas por rodada" value={round} onChange={e=>setRound(e.target.value)}><option value="">Todas as rodadas</option>{[...new Set(allMatches.map((m:any)=>m.round))].sort((a:any,b:any)=>a-b).map((r:any)=><option value={r} key={r}>{r}ª rodada</option>)}</select><select aria-label="Filtrar estatísticas por clube" value={clubFilter} onChange={e=>setClubFilter(e.target.value)}><option value="">Todos os clubes</option>{clubs.map((c:any)=><option value={c.id} key={c.id}>{c.name}</option>)}</select></div><div className="tabs">{[['','Artilharia'],['assists','Assistências'],['contributions','Participações'],['rating','Melhores notas'],['clubs','Clubes']].map(([v,l])=><button className={category===v?'active':''} onClick={()=>setCategory(v)} key={v}>{l}</button>)}</div>{external?<ExternalRankings data={scopedExternal}/>:category==='clubs'?<><div className="cards three">{[...standing].filter((c:any)=>c.played).sort((a,b)=>b.gf-a.gf).map((c:any)=><a href={'/clubes/'+c.id} className="panel padded" key={c.id}><Badge club={c}/><h3>{c.name}</h3><p>{c.gf} gols marcados · {c.ga} sofridos</p><strong>{Math.round(c.points/(c.played*3)*100)}% de aproveitamento</strong><p>{c.form.slice().reverse().findIndex((f:string)=>f==='D')===-1?c.form.length:c.form.slice().reverse().findIndex((f:string)=>f==='D')} jogos sem perder</p></a>)}</div><Section title="Maiores goleadas"><div className="cards three">{allMatches.filter((m:any)=>m.status==='Encerrado').sort((a:any,b:any)=>Math.abs(b.home_score-b.away_score)-Math.abs(a.home_score-a.away_score)).slice(0,6).map((m:any)=><Match key={m.id} m={m}/>)}</div></Section>{!allMatches.length&&<Empty icon={BarChart3} title="Os números começam no primeiro jogo"/>}</>:<div className="panel"><Rankings metric={category||'goals'}/></div>}<p className="muted">Gols e assistências vêm dos lances cadastrados. Jogos e notas vêm das participações registradas no painel.</p></>;
else if(path==='/noticias')content=<><Heading title="A liga também é notícia." kicker="CENTRAL DE NOTÍCIAS" sub="Resultados, bastidores e as histórias que merecem ser contadas."/><div className="filters"><Search size={18}/><input aria-label="Buscar notícias" placeholder="O que você procura?" value={search} onChange={e=>setSearch(e.target.value)}/><select aria-label="Categoria" value={category} onChange={e=>setCategory(e.target.value)}><option value="">Todas as categorias</option>{specs.news.fields.find(f=>f.key==='category')?.options?.map(c=><option key={c}>{c}</option>)}</select></div>{sNews.filter((n:any)=>(!category||n.category===category)&&n.title.toLowerCase().includes(search.toLowerCase())).length?<div className="cards three">{sNews.filter((n:any)=>(!category||n.category===category)&&n.title.toLowerCase().includes(search.toLowerCase())).map((n:any)=><NewsCard n={n} key={n.id}/>)}</div>:<Empty icon={Newspaper} title="As manchetes estão a caminho" text="Nenhuma notícia publicada para esta busca."/>}</>;
else if(path.startsWith('/noticias/')){const n=d.news.find((n:any)=>n.id===path.split('/')[2]);content=n?<article className="article"><a href="/noticias" className="back"><ArrowLeft size={15}/>Todas as notícias</a><span className="eyebrow">{n.category}</span><h1>{n.title}</h1><p className="article-deck">{n.summary}</p><div className="article-meta"><span>Por {n.author} · {date(n.created_at,true)}</span><Share/></div>{n.image&&<img className="article-cover" src={n.image} alt=""/>}<Content text={n.body}/>{n.video&&<Video url={n.video}/>}<div className="filters">{n.club_id&&<a className="button outline" href={'/clubes/'+n.club_id}>Sobre {club(n.club_id)?.name}</a>}{n.player_id&&<a className="button outline" href={'/jogadores/'+n.player_id}>{player(n.player_id)?.name}</a>}{n.match_id&&<a className="button outline" href={'/jogos/'+n.match_id}>Ver partida</a>}</div></article>:<NotFound/>}
else if(path==='/videos')content=<><Heading title="Dá o play na emoção." kicker="LANCES E MELHORES MOMENTOS" sub="O futebol que merece ser visto outra vez."/><div className="tabs">{['','Golaços','Defesas','Melhores lances','Compilações'].map(c=><button className={category===c?'active':''} key={c} onClick={()=>setCategory(c)}>{c||'Todos os vídeos'}</button>)}</div><Videos list={d.videos.filter((v:any)=>(!category||v.category===category)&&(!v.season_id||v.season_id===seasonId))}/></>;
else if(path.startsWith('/videos/')){const v=d.videos.find((v:any)=>v.id===path.split('/')[2]);content=v?<><Heading title={v.title} kicker={v.category}><Share/></Heading><Video url={v.url}/>{v.match_id&&<a className="button outline" href={'/jogos/'+v.match_id}>Ir para a partida <ArrowUpRight size={16}/></a>}</>:<NotFound/>}
else if(path==='/museu')content=<><div className="museum-hero"><span className="eyebrow">O TEMPO PASSA. A GLÓRIA FICA.</span><h1>O lugar dos<br/><em>inesquecíveis.</em></h1><p>As conquistas, os recordes e as camisas que<br/>escreveram a história do Brasileirão eFootball.</p><Trophy className="museum-trophy" strokeWidth={1}/></div><Section title="A galeria dos campeões" kicker="ETERNIZADOS">{d.titles.length?<div className="cards three">{d.titles.map((t:any)=><a href={'/temporadas/'+t.season_id} className="champion-card" key={t.id}><span className="eyebrow">{d.seasons.find((s:any)=>s.id===t.season_id)?.name}</span><Trophy/><Badge club={club(t.club_id)} size="large"/><h2>{club(t.club_id)?.name}</h2><p>{t.name}</p><span>Explore esta conquista <ArrowUpRight size={15}/></span></a>)}</div>:<Empty icon={Trophy} title="Toda grande história tem um começo" text="Os campeões serão eternizados aqui após a conclusão de cada temporada."/>}</Section><Section title="Os maiores da liga" kicker="RANKING HISTÓRICO"><div className="panel padded">{clubs.map((c:any)=>({...c,total:d.titles.filter((t:any)=>t.club_id===c.id).length})).filter((c:any)=>c.total).sort((a:any,b:any)=>b.total-a.total).map((c:any,i:number)=><div className="list-line" key={c.id}><a className="table-club" href={'/clubes/'+c.id}>{i+1}. <Badge club={c}/>{c.name}</a><strong>{c.total} título(s)</strong></div>)}{!d.titles.length&&<p className="muted">A primeira taça abrirá esta disputa.</p>}</div></Section><Section title="Nomes que ficam" kicker="HALL DA FAMA E RECORDES"><div className="cards three">{d.awards.filter((a:any)=>['Hall da Fama','Recorde'].includes(a.name)).map((a:any)=><div className="award-card" key={a.id}><Medal/><span className="eyebrow">{a.name}</span><h3>{player(a.player_id)?.name||club(a.club_id)?.name}</h3><p>{a.description}</p></div>)}</div></Section></>;
else if(path.startsWith('/temporadas/')){const s=d.seasons.find((s:any)=>s.id===path.split('/')[2]);content=s?<><Heading title={s.name} kicker="MEMÓRIA DA LIGA" sub={s.status}/>{d.titles.filter((t:any)=>t.season_id===s.id).map((t:any)=><div className="panel padded" key={t.id}>{t.image&&<img className="article-cover" src={t.image} alt="Foto da conquista"/>}<Trophy/><h2>{club(t.club_id)?.name} — Campeão</h2><p>Vice-campeão: {club(t.runner_id)?.name||'Não informado'}</p><Content text={t.story}/></div>)}<Section title="Jogos da edição"><div className="cards three">{d.matches.filter((m:any)=>m.season_id===s.id).map((m:any)=><Match m={m} key={m.id}/>)}</div></Section></>:<NotFound/>}
else if(path==='/premiacoes')content=<><Heading title="Talento que merece aplausos." kicker="PREMIAÇÕES" sub="Os grandes nomes de cada rodada e de cada temporada."/>{scopedAwards.length?<div className="cards three">{scopedAwards.map((a:any)=><div className="award-card" key={a.id}><Medal/><span className="eyebrow">{a.name}</span><h2>{player(a.player_id)?.name||club(a.club_id)?.name}</h2><p>{a.description}</p><small>{a.round?a.round+'ª rodada':season?.name}</small></div>)}</div>:<Empty icon={Medal} title="O reconhecimento vem com o jogo" text="As premiações serão publicadas pela organização."/>}</>;
else if(path==='/transferencias')content=<><Heading title="O mercado se movimenta." kicker="TRANSFERÊNCIAS" sub="As negociações e as mudanças de camisa da liga."/>{transfers.length?<div className="panel padded">{transfers.map((t:any)=><div className="transfer-row" key={t.id}><span className="avatar"><ArrowLeftRight/></span><div className="grow"><a href={'/jogadores/'+t.player_id}><h3>{player(t.player_id)?.name}</h3></a><p>{club(t.from_id)?.name||'Sem clube'} → {club(t.to_id)?.name}</p><small>{date(t.date)} · Confirmada</small></div><strong>{t.value!=null?money(t.value):'Valor não divulgado'}</strong>{t.news_id&&<a href={'/noticias/'+t.news_id}><ArrowUpRight/></a>}</div>)}</div>:<Empty icon={ArrowLeftRight} title="De olho na janela" text="Nenhuma transferência confirmada nesta temporada."/>}</>;
else if(path==='/regulamento')content=<><Heading title="O jogo tem suas regras." kicker="REGULAMENTO" sub={season?.name||'Regulamento da competição'}/><div className="panel padded">{season?.rules?<Content text={season.rules}/>:<Empty icon={BookOpen} title="Regulamento em preparação" text="O documento oficial será publicado pela organização."/>}</div></>;
else if(path==='/comparar'){const a=standing.find((x:any)=>x.id===compareA),b=standing.find((x:any)=>x.id===compareB);content=<><Heading title="Lado a lado." kicker="COMPARAÇÃO ENTRE CLUBES"/><div className="filters">{[[compareA,setCompareA],[compareB,setCompareB]].map(([val,set]:any,i)=><select key={i} aria-label={'Clube '+(i+1)} value={val} onChange={e=>set(e.target.value)}><option value="">Escolha o clube {i+1}</option>{clubs.map((c:any)=><option key={c.id} value={c.id}>{c.name}</option>)}</select>)}</div>{a&&b?<div className="panel padded"><div className="compare-head"><Badge club={a} size="large"/><h2>{a.name} × {b.name}</h2><Badge club={b} size="large"/></div>{[['points','Pontos'],['played','Jogos'],['wins','Vitórias'],['gf','Gols marcados'],['ga','Gols sofridos'],['gd','Saldo de gols']].map(([k,l])=><div className="comparison" key={k}><strong>{a[k]}</strong><span>{l}</span><strong>{b[k]}</strong></div>)}</div>:<Empty icon={ArrowLeftRight} title="Dois clubes. Todos os números." text="Escolha dois clubes com partidas ou elencos na temporada."/>}<Section title="Confrontos diretos"><div className="cards three">{allMatches.filter((m:any)=>compareA&&compareB&&m.home_id!==m.away_id&&[compareA,compareB].includes(m.home_id)&&[compareA,compareB].includes(m.away_id)).map((m:any)=><Match m={m} key={m.id}/>)}</div></Section></>}
else content=<NotFound/>;
return <><a className="skip-link" href="#conteudo">Pular para o conteúdo</a><div className="topbar"><div className="container"><span>FUTEBOL VIRTUAL. PAIXÃO BRASILEIRA.</span><div><a href="/regulamento">Regulamento</a><a href="/admin"><Shield size={12}/> Área da liga <ArrowUpRight size={12}/></a></div></div></div><header><div className="container header-main"><a className="brand" href="/"><img src={logoSrc} alt=""/><span>BRASILEIRÃO<small>EFOOTBALL</small></span></a><div className="header-center">A CASA DA NOSSA LIGA<span>ESPORTS · COMUNIDADE · COMPETIÇÃO</span></div><div className="header-tools"><button aria-label="Abrir busca" className="icon-button" onClick={()=>setSearchOpen(true)}><Search size={20}/></button><select className="season-select" aria-label="Temporada" value={seasonId} onChange={e=>{setSeasonId(e.target.value);setRound('')}}>{!d.seasons.length&&<option>Temporada</option>}{d.seasons.map((s:any)=><option value={s.id} key={s.id}>{s.name}</option>)}</select><button className="icon-button mobile-menu" aria-label="Abrir menu" onClick={()=>setNav(!nav)}>{nav?<X/>:<Menu/>}</button></div></div><div className={'nav-wrap '+(nav?'open':'')}><nav className="container">{links.map(([href,label])=><a key={href} href={href} className={path===href||href!=='/'&&path.startsWith(href+'/')?'active':''}>{label}</a>)}<a className="nav-live" href="/jogos"><span className="green-dot"/>Central da rodada <ArrowUpRight size={14}/></a></nav></div></header><main className={'container '+(admin?'admin-main':'')} id="conteudo"><div className="mobile-season"><label>Temporada <select aria-label="Selecionar temporada no celular" value={seasonId} onChange={e=>{setSeasonId(e.target.value);setRound('')}}>{!d.seasons.length&&<option>A definir</option>}{d.seasons.map((s:any)=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label></div>{error&&<div role="alert" className="error-banner"><AlertCircle size={18}/>{error}<button onClick={load}>Tentar novamente</button></div>}{!data&&!error?<div className="loading"><RefreshCw className="spin"/><h3>Preparando o campo…</h3></div>:content}</main>{!admin&&<>{d.sponsors.length>0&&<div className="container sponsors"><span className="eyebrow">QUEM JOGA JUNTO</span><div>{d.sponsors.map((s:any)=><a href={s.url||'#'} key={s.id} target="_blank" rel="noopener noreferrer"><img src={s.image} alt={s.name}/></a>)}</div></div>}<footer><div className="container footer-grid"><div><a className="brand" href="/"><img src={logoSrc} alt=""/><span>BRASILEIRÃO<small>EFOOTBALL</small></span></a><p>O jogo é virtual. A paixão é nossa.</p></div><div><b>A competição</b><a href="/jogos">Jogos e calendário</a><a href="/classificacao">Classificação</a><a href="/clubes">Clubes e elencos</a><a href="/regulamento">Regulamento</a></div><div><b>Dentro da liga</b><a href="/noticias">Notícias</a><a href="/transferencias">Transferências</a><a href="/premiacoes">Premiações</a><a href="/museu">Museu da liga</a></div><div><b>Organização</b><a href="/admin">Painel administrativo</a><a href="/comparar">Comparar clubes</a><a href="/videos">Lances e vídeos</a></div></div><div className="container footer-bottom"><span>© {new Date().getFullYear()} Brasileirão eFootball. A nossa liga.</span><span>Competição independente · Sem vínculo oficial com a KONAMI.</span></div></footer></>}{searchOpen&&<div className="modal-overlay" onClick={()=>setSearchOpen(false)}><section className="search-modal" role="dialog" aria-modal="true" aria-label="Busca global" onClick={e=>e.stopPropagation()}><div className="modal-head"><h2>Encontre na liga</h2><button className="icon-button" aria-label="Fechar busca" onClick={()=>setSearchOpen(false)}><X/></button></div><div className="filters"><Search/><input autoFocus placeholder="Clube, jogador ou notícia…" value={search} onChange={e=>setSearch(e.target.value)} aria-label="Buscar"/></div>{search.trim()?<div className="search-results">{[['clubs','clubes','Clubes'],['players','jogadores','Jogadores'],['news','noticias','Notícias']].map(([entity,route,label])=><section key={entity}><span className="eyebrow">{label}</span>{d[entity].filter((v:any)=>(v.name||v.title).toLowerCase().includes(search.toLowerCase())).slice(0,8).map((v:any)=><a href={'/'+route+'/'+v.id} key={v.id}>{v.name||v.title}<ArrowUpRight size={16}/></a>)}</section>)}</div>:<p className="muted">Digite para pesquisar o conteúdo publicado.</p>}</section></div>}</>}
function NotFound(){return <div className="not-found"><span className="eyebrow">FORA DAS QUATRO LINHAS</span><h1>404</h1><h2>Esse lance não foi encontrado.</h2><p>A página pode ter mudado ou ainda não foi publicada.</p><a className="button" href="/">Voltar ao início <ArrowRight size={16}/></a></div>}
function ExternalMatches({data}:any){const snapshots=data.filter((x:any)=>x.kind==='matches');return snapshots.length?<Section title="Resultados recebidos do Copa Fácil" kicker="DADOS DA ORIGEM"><p className="muted">Status exibidos como recebidos. O painel deve mapear esses status para incluir os jogos na central.</p>{snapshots.map((s:any)=><div key={s.id} className="panel padded"><h3>{s.data.stage} · {s.data.round}</h3>{s.data.matches.map((m:any)=><div className="list-line" key={m.id}><span>{m.teams?.team_1?.name} {m.result?.pts1??'–'} × {m.result?.pts2??'–'} {m.teams?.team_2?.name}</span><span className="tag">{m.status}</span></div>)}</div>)}</Section>:null}
function ExternalRankings({data}:any){const ranks=data.filter((x:any)=>x.kind==='ranking');return ranks.length?<div className="cards two">{ranks.map((r:any)=><div className="panel padded" key={r.id}><h2>{r.data.title}</h2><div className="table-wrap"><table><thead><tr><th>Jogador</th><th>Clube</th>{r.data.header?.map((h:string,i:number)=><th key={i}>{h}</th>)}</tr></thead><tbody>{r.data.players?.map((p:any,i:number)=><tr key={i}><td>{p.name}</td><td>{p.teamName}</td>{p.data?.map((v:string,j:number)=><td key={j}>{v}</td>)}</tr>)}</tbody></table></div></div>)}</div>:<Empty icon={Target} title="Aguardando os rankings da origem"/>}
function Admin({d,load}:any){
const [tab,setTab]=useState('overview'),[edit,setEdit]=useState<any>(null),[values,setValues]=useState<any>({}),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[failure,setFailure]=useState(''),[q,setQ]=useState(''),[preview,setPreview]=useState(false),[conf,setConf]=useState<any>(d.config||{}),[apiKey,setApiKey]=useState(''),[mapping,setMapping]=useState(JSON.stringify(d.config?.statusMap||{},null,2)),[email,setEmail]=useState(''),[role,setRole]=useState('editor'),[temporaryPassword,setTemporaryPassword]=useState('');
const label=(entity:string,id:string):string=>{const r=d[entity]?.find((x:any)=>x.id===id);return r?((entity==='rounds'?`${r.name} · ${label('phases',r.phase_id)}`:entity==='phases'?`${r.name} · ${label('seasons',r.season_id)}`:null)||r.name||r.title||(entity==='matches'?`${label('clubs',r.home_id)} × ${label('clubs',r.away_id)} · R${r.round}`:entity==='memberships'?`${label('players',r.player_id)} · ${label('clubs',r.club_id)}`:r.player_id?label('players',r.player_id):r.type?`${r.type} · ${r.minute}'`:r.id)):id||'—'};
async function action(body:any,url='/api/admin'){setBusy(true);setFailure('');setNotice('');try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j:any=await r.json();if(!r.ok)throw new Error(j.error||'Não foi possível concluir.');await load();setNotice(j.message||'Alterações salvas com sucesso.');return j}catch(e:any){setFailure(e.message);return null}finally{setBusy(false)}}
function newRecord(row?:any){const obj:any={};for(const f of specs[tab].fields)obj[f.key]=(f.type==='datetime-local'&&row?.[f.key]?new Date(new Date(row[f.key]).getTime()-new Date(row[f.key]).getTimezoneOffset()*60000).toISOString().slice(0,16):row?.[f.key])??(f.type==='select'?f.options?.[0]||'':f.type==='color'?'#087653':f.key==='season_id'?d.seasons.find((s:any)=>s.status==='Em andamento')?.id||d.seasons[0]?.id||'':'');setValues(obj);setEdit({id:row?.id||crypto.randomUUID(),existing:!!row});setPreview(false);setFailure('')}
async function save(e:any){e.preventDefault();if(await action({action:'save',entity:tab,id:edit.id,data:values}))setEdit(null)}
async function upload(file:File|undefined,key:string){if(!file)return;setBusy(true);setFailure('');try{const form=new FormData();form.set('file',file);const r=await fetch('/api/upload',{method:'POST',body:form});const j:any=await r.json();if(!r.ok)throw new Error(j.error);setValues((v:any)=>({...v,[key]:j.url}))}catch(e:any){setFailure(e.message)}finally{setBusy(false)}}
async function backup(){const result=await action({action:'export'});if(!result)return;const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='brasileirao-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(url)}
if(!d.user||d.needsSetup)return <AuthPanel d={d} load={load}/>;
if(!d.user.role)return <><Empty icon={Shield} title="Acesso restrito à organização" text="Peça ao administrador para autorizar seu e-mail como editor ou administrador."/><button className="button outline" onClick={async()=>{await fetch('/api/auth',{method:'POST',body:JSON.stringify({action:'logout'})});load()}}>Sair e usar outra conta</button></>;
const modules=Object.entries(specs).filter(([k])=>d.user.role==='admin'||['news','videos','banners'].includes(k));
return <><div className="admin-top"><div><span className="eyebrow">CENTRAL DA ORGANIZAÇÃO</span><h1>Sua liga, sob controle.</h1><p>Olá, {d.user.email} <span className="tag green">{d.user.role==='admin'?'Administrador':'Editor'}</span></p></div><a className="button outline" href="/">Ver portal <ExternalLink size={16}/></a></div><div className="admin-layout"><aside className="admin-sidebar"><button className={tab==='overview'?'active':''} onClick={()=>setTab('overview')}><LayoutDashboard size={17}/> Visão geral</button><span className="eyebrow">GERENCIAR A LIGA</span>{modules.map(([k,s])=><button className={tab===k?'active':''} key={k} onClick={()=>{setTab(k);setQ('');setNotice('')}}>{k==='clubs'?<Shield size={16}/>:k==='matches'?<CalendarDays size={16}/>:k==='players'?<Users size={16}/>:k==='news'?<Newspaper size={16}/>:k==='videos'?<Play size={16}/>:k==='titles'?<Trophy size={16}/>:<ChevronRight size={16}/>} {s.label}</button>)}{d.user.role==='admin'&&<><span className="eyebrow">CONFIGURAÇÕES</span><button className={tab==='integration'?'active':''} onClick={()=>setTab('integration')}><RefreshCw size={16}/>Copa Fácil</button><button className={tab==='members'?'active':''} onClick={()=>setTab('members')}><Shield size={16}/>Permissões</button><button className={tab==='logs'?'active':''} onClick={()=>setTab('logs')}><Activity size={16}/>Histórico e backup</button></>}<button onClick={async()=>{await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});load()}}><LogOut size={16}/>Sair da conta</button></aside><div className="admin-content" key={tab}>{notice&&<div className="notice" role="status"><Check size={17}/>{notice}</div>}{failure&&<div className="error-banner" role="alert"><AlertCircle size={17}/>{failure}</div>}
{tab==='overview'?<><h2>O panorama do campeonato</h2><div className="stat-boxes">{[['Clubes',d.clubs.length],['Jogadores',d.players.length],['Partidas',d.matches.length],['Notícias',d.news.length]].map(([l,v])=><div key={l}><strong>{v}</strong><span>{l}</span></div>)}</div><div className="panel padded"><span className="eyebrow">ORGANIZE O PRIMEIRO APITO</span><h2>Do cadastro ao campo.</h2><p className="muted">Siga esta sequência para conectar os dados do campeonato.</p>{[['seasons','01','Defina a temporada','Nome, regulamento, vagas e critérios de desempate.'],['clubs','02','Apresente os clubes','Escudos, cores e responsáveis por cada equipe.'],['players','03','Monte os elencos','Cadastre os jogadores e vincule-os na seção Elencos.'],['matches','04','Coloque a bola em jogo','Rodadas, partidas, resultados e eventos de cada confronto.']].map(([k,n,t,s])=><button className="setup-step" key={k} onClick={()=>setTab(k)}><span>{n}</span><div><h3>{t}</h3><p>{s}</p></div><ArrowRight size={20}/></button>)}</div><div className="panel padded admin-help"><h3>Resultados e estatísticas</h3><a href="/apostas" className="button outline">Gerenciar Liga Bet <ArrowUpRight size={16}/></a><p>Cadastre o placar em Partidas. Registre os autores dos gols e assistências em Lances; esses eventos alimentam os rankings sem alterar o placar informado. Registre Participações para contabilizar jogos e notas dos jogadores.</p><p>Uma transferência confirmada encerra o vínculo anterior e cria o novo automaticamente. O histórico fica preservado.</p></div></>:specs[tab]?<><div className="section-heading"><div><span className="eyebrow">GESTÃO DA LIGA</span><h2>{specs[tab].label}</h2>{tab==='player_totals'&&<p className="muted">Estes totais substituem os gols e assistências calculados dos lances na temporada. Atualize o total após novos jogos; remova-o somente quando todos os lances estiverem cadastrados e conferidos.</p>}</div><button className="button" onClick={()=>newRecord()}><Plus size={17}/>Adicionar</button></div><div className="filters"><Search size={18}/><input placeholder={'Buscar em '+specs[tab].label.toLowerCase()} aria-label="Buscar registros" value={q} onChange={e=>setQ(e.target.value)}/><span className="muted">{d[tab].length} registro(s)</span></div><div className="panel">{d[tab].length?<div className="admin-records">{d[tab].filter((r:any)=>JSON.stringify(r).toLowerCase().includes(q.toLowerCase())||label(tab,r.id).toLowerCase().includes(q.toLowerCase())).map((r:any)=><div className="admin-record" key={r.id}>{r.image?<img src={r.image} alt=""/>:<span className="avatar"><Flag size={18}/></span>}<div className="grow"><strong>{label(tab,r.id)}</strong><small>{r.status||r.position||r.description||r.type||r.manager||''}{r.season_id?' · '+label('seasons',r.season_id):''}{r.source==='copafacil'?' · Copa Fácil':''}</small></div>{r.source!=='copafacil'&&<><button className="icon-button" aria-label={'Editar '+label(tab,r.id)} onClick={()=>newRecord(r)}><Pencil size={16}/></button><button className="icon-button danger" aria-label={'Excluir '+label(tab,r.id)} onClick={()=>{if(confirm('Excluir “'+label(tab,r.id)+'”? Esta ação não pode ser desfeita.'))action({action:'delete',entity:tab,id:r.id})}} disabled={busy}><Trash2 size={16}/></button></>}</div>)}</div>:<Empty title={'Nenhum registro em '+specs[tab].label.toLowerCase()} text="Clique em Adicionar para começar. As informações serão salvas no banco da liga."/>}</div></>:tab==='integration'?<><span className="eyebrow">DADOS CONECTADOS</span><h2>Integração Copa Fácil</h2><p className="muted">API v2 · consultas no servidor · cache persistente · sem promessa de tempo real instantâneo.</p><form className="panel padded settings-form" onSubmit={async e=>{e.preventDefault();let statusMap;try{statusMap=JSON.parse(mapping);if(!statusMap||Array.isArray(statusMap)||typeof statusMap!=='object')throw 0}catch{setFailure('O mapa de status precisa ser um objeto JSON válido.');return}if(await action({action:'settings',data:{...conf,statusMap},apiKey}))setApiKey('')}}><div className="form-grid"><label>ID do campeonato<input required value={conf.tournament||''} onChange={e=>setConf({...conf,tournament:e.target.value})}/></label><label>Chave da API<input type="password" autoComplete="new-password" placeholder={d.hasKey?'Chave salva. Preencha só para substituir.':'Cole a chave obtida no aplicativo'} value={apiKey} onChange={e=>setApiKey(e.target.value)}/><small>A chave é salva apenas no servidor e nunca retornada ao navegador.</small></label><label>Fonte dos dados<select value={conf.mode||'local'} onChange={e=>setConf({...conf,mode:e.target.value})}><option value="local">Gerenciamento manual (dados locais)</option><option value="external">Dados do Copa Fácil</option></select></label><label>Temporada de destino<select value={conf.season_id||''} onChange={e=>setConf({...conf,season_id:e.target.value})}><option value="">Selecione</option>{d.seasons.map((s:any)=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>Intervalo de atualização (minutos)<input type="number" min="5" max="1440" value={conf.interval||15} onChange={e=>setConf({...conf,interval:+e.target.value})}/></label><label className="checkbox-label"><input type="checkbox" checked={!!conf.enabled} onChange={e=>setConf({...conf,enabled:e.target.checked})}/>Sincronização automática no servidor</label></div><fieldset><legend>Dados a sincronizar</legend><div className="checks">{[['stages','Fases'],['table','Classificação'],['matches','Rodadas e partidas'],['rankings','Rankings'],['teams','Equipes'],['players','Relatório de jogadores']].map(([k,l])=><label className="checkbox-label" key={k}><input type="checkbox" checked={(conf.modules||[]).includes(k)} onChange={e=>setConf({...conf,modules:e.target.checked?[...(conf.modules||[]),k]:(conf.modules||[]).filter((x:string)=>x!==k)})}/>{l}</label>)}</div></fieldset><label>Mapa de status da origem para o portal<textarea rows={5} value={mapping} onChange={e=>setMapping(e.target.value)} spellCheck={false}/><small>Após testar a conexão e sincronizar, use os status recebidos abaixo como chaves. Valores permitidos: Agendado, Ao vivo, Encerrado e Adiado. Exemplo de formato: {'{"STATUS_RECEBIDO":"Encerrado"}'}. Valores desconhecidos não entram na classificação local.</small></label><button className="button" disabled={busy}>Salvar configuração <Check size={16}/></button></form><div className="filters"><button className="button outline" disabled={busy} onClick={()=>action({action:'test'},'/api/sync')}>Testar conexão</button><button className="button" disabled={busy} onClick={()=>action({action:'sync'},'/api/sync')}><RefreshCw size={16} className={busy?'spin':''}/>Sincronizar agora</button><span className="muted">Última atualização: {d.config?.lastSync?date(d.config.lastSync,true):'Ainda não realizada'}</span></div><div className="notice"><Clock size={18}/><span>Com esta opção ativada, o servidor sincroniza no intervalo escolhido, mesmo com o painel fechado. Configure o agendamento no Supabase conforme o README. Ativar esta opção sozinho não cria o agendamento. Os dados locais continuam disponíveis sem a integração.</span></div><details className="panel padded"><summary>Consultar dados recebidos e status da origem</summary>{(d.external||[]).length?d.external.map((r:any)=><details key={r.id}><summary>{r.kind} · {r.id}</summary><pre>{JSON.stringify(r.data,null,2)}</pre></details>):<p>Nenhuma resposta importada.</p>}</details><Section title="Histórico de sincronização"><div className="panel padded">{d.syncRuns?.map((r:any)=><div className="list-line" key={r.id}><span className={r.status==='Erro'?'danger':''}>{r.status} · {r.message}</span><small>{date(r.created_at,true)}</small></div>)}{!d.syncRuns?.length&&<p className="muted">Nenhuma sincronização executada.</p>}</div></Section></>:tab==='members'?<><h2>Quem cuida da liga</h2><ChangePassword/><p className="muted">Administradores gerenciam todos os módulos. Editores publicam notícias, vídeos e destaques. O público acessa o portal sem login. O painel exige e-mail e senha de uma conta autorizada. Crie e confirme a conta primeiro no Supabase → Authentication → Users. Depois autorize o e-mail aqui.</p><form className="panel padded settings-form" onSubmit={async e=>{e.preventDefault();if(await action({action:'member',email,role,temporaryPassword})){setEmail('');setTemporaryPassword('')}}}><div className="form-grid"><label>E-mail da conta<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Permissão<select value={role} onChange={e=>setRole(e.target.value)}><option value="editor">Editor</option><option value="admin">Administrador</option></select></label></div><button className="button" disabled={busy}><Plus size={16}/>Autorizar e-mail</button></form><div className="panel padded">{d.members?.map((m:any)=><div className="list-line" key={m.id}><div><b>{m.email}</b><small>{m.role==='admin'?'Administrador':'Editor'}{m.id.startsWith('invite:')?' · Aguardando primeiro acesso':''}</small></div>{m.id!==d.user.id&&<button aria-label="Remover permissão" className="icon-button danger" onClick={()=>{if(confirm('Remover o acesso desta conta?'))action({action:'remove-member',id:m.id})}}><Trash2 size={16}/></button>}</div>)}</div></>:tab==='logs'?<><div className="section-heading"><h2>Histórico e backup</h2><button className="button" onClick={backup} disabled={busy}><Download size={17}/>Exportar JSON</button></div><p className="muted">Exportação completa dos registros e do histórico de alterações. Credenciais e permissões não são incluídas. Guarde as imagens separadamente; o arquivo contém as referências aos arquivos.</p><div className="panel padded">{d.logs?.map((l:any)=><div className="list-line" key={l.id}><div><strong>{l.action} · {specs[l.entity]?.label||l.entity}</strong><small>{d.members?.find((m:any)=>m.id===l.actor)?.email||l.actor}</small></div><small>{date(l.created_at,true)}</small></div>)}{!d.logs?.length&&<Empty small icon={Activity} title="Tudo começa por aqui" text="As alterações realizadas serão registradas neste histórico."/>}</div></>:null}
</div></div>{edit&&specs[tab]&&<div className="modal-overlay"><div className="editor-modal" role="dialog" aria-modal="true" aria-label={specs[tab].singular}><div className="modal-head"><div><span className="eyebrow">{edit.existing?'EDITAR':'NOVO REGISTRO'}</span><h2>{specs[tab].singular}</h2></div><button aria-label="Fechar editor" className="icon-button" onClick={()=>setEdit(null)}><X/></button></div>{failure&&<div className="error-banner" role="alert">{failure}</div>}<form onSubmit={save}>{preview?<div className="form-preview">{values.image&&<img src={values.image} alt="Prévia"/>}<span className="eyebrow">PRÉ-VISUALIZAÇÃO · AINDA NÃO SALVO</span><h2>{values.title||values.name||specs[tab].singular}</h2>{specs[tab].fields.filter(f=>values[f.key]&&!['image','title','name'].includes(f.key)).map(f=><div key={f.key}><b>{f.label}</b><Content text={f.ref?label(f.ref,values[f.key]):String(values[f.key])}/></div>)}</div>:<div className="form-grid">{specs[tab].fields.map(f=><label className={['textarea','image'].includes(f.type||'')?'full':''} key={f.key}>{f.label}{f.required&&<span className="required"> *</span>}{f.type==='textarea'?<><div className="format-toolbar">{[['**Texto em destaque**','Negrito'],['*Texto em itálico*','Itálico'],['\n## Título\n','Título'],['https://','Link']].map(([v,l])=><button key={l} type="button" onClick={()=>setValues({...values,[f.key]:(values[f.key]||'')+v})}>{l}</button>)}</div><textarea rows={f.key==='body'||f.key==='rules'?10:4} required={f.required} value={values[f.key]||''} onChange={e=>setValues({...values,[f.key]:e.target.value})}/></>:f.type==='ref'||f.type==='select'?<select required={f.required} value={values[f.key]||''} onChange={e=>setValues({...values,[f.key]:e.target.value})}><option value="">Selecione</option>{f.ref?d[f.ref].filter((r:any)=>f.ref!=='rounds'||!values.season_id||d.phases.some((p:any)=>p.id===r.phase_id&&p.season_id===values.season_id)).map((r:any)=><option key={r.id} value={r.id}>{label(f.ref!,r.id)}</option>):f.options?.map(o=><option key={o}>{o}</option>)}</select>:f.type==='image'?<div className="image-input"><input placeholder="URL HTTPS da imagem ou envie um arquivo" required={f.required} value={values[f.key]||''} onChange={e=>setValues({...values,[f.key]:e.target.value})}/><label className="upload-button"><Upload size={16}/>Enviar imagem<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>upload(e.target.files?.[0],f.key)} disabled={busy}/></label>{values[f.key]&&<img src={values[f.key]} alt="Prévia da imagem"/>}</div>:<input type={f.type||'text'} min={f.type==='number'?0:undefined} step={['rating','value'].includes(f.key)?'0.1':undefined} required={f.required} value={values[f.key]??''} onChange={e=>setValues({...values,[f.key]:e.target.value})}/>}</label>)}</div>}<div className="modal-actions"><button type="button" className="button outline" onClick={()=>setPreview(!preview)}><Eye size={16}/>{preview?'Voltar à edição':'Pré-visualizar'}</button><button type="submit" className="button" disabled={busy}>{busy?<RefreshCw size={16} className="spin"/>:<Check size={16}/>}Salvar {values.status==='Publicado'?'e publicar':''}</button></div></form></div></div>}</>}
